  // CSD_RATIONALE_BEGIN
  // Tracks only the current generated parser-valid prefix and a step counter.
  // On each step it inspects the number of valid next tokens: when the grammar
  // frontier is narrow it uses fully constrained decoding, and otherwise it uses
  // a softly constrained step that still prefers grammar-valid continuations.
  // This keeps generation inside the parser's format requirements, which is
  // suitable for step-by-step math solutions with arithmetic written inside
  // << >> delimiters.
  // CSD_RATIONALE_END
  generated := currentPrefix;
  helpers.cost := 0;
  cost := 0;
  var suffix: Prefix := [];
  var steps: nat := 0;

  while steps < maxSteps
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant parser.IsValidPrefix(generated)
    invariant generated == currentPrefix + suffix
    invariant |suffix| == steps
    invariant helpers.cost <= steps
    decreases maxSteps - steps
  {
    if parser.IsCompletePrefix(generated) {
      break;
    } else {
      var validCount := helpers.ValidTokenCount(parser, generated);
      if validCount <= 6 {
        var next := helpers.ConstrainedStep(lm, parser, prompt, generated, eosToken);
        if next == eosToken {
          break;
        } else {
          generated := generated + [next];
          suffix := suffix + [next];
          steps := steps + 1;
        }
      } else {
        var next, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, generated, 4.0, eosToken);
        if next == eosToken {
          break;
        } else {
          if isValid {
            generated := generated + [next];
            suffix := suffix + [next];
            steps := steps + 1;
          } else {
            break;
          }
        }
      }
    }
  }
  cost := helpers.cost;
}

