{
  // CSD_RATIONALE_BEGIN
  // The prior strategy only *boosted* the delimiter tokens and still let the model pick
  // arbitrary valid tokens. The evaluation traces show that this was too weak: outputs
  // often stopped after a short fragment like "A" or "1/10 of", and no << >> segment
  // was ever actually emitted.
  //
  // This revision makes delimiter insertion explicit rather than merely preferred.
  // Whenever "<<" is a valid next token and we are not already inside a computation
  // segment, the strategy emits "<<" directly. Likewise, whenever ">>" is valid and we
  // are inside a computation segment, it emits ">>" directly. This guarantees that if
  // the parser allows the required delimiters, they are actually produced instead of
  // being outcompeted by ordinary words.
  //
  // To avoid producing only a bare empty segment, the strategy tracks whether at least
  // one non-delimiter token has been generated since entering "<<". It only closes with
  // ">>" after some content has appeared, unless forced by step budget or parser state.
  // Between forced delimiter emissions it uses constrained decoding so parser validity is
  // preserved. EOS is always checked before appending, as required.
  //
  // Overall, the key change is replacing soft encouragement with hard insertion of << >>
  // when valid, directly targeting the observed missing_constrained_segment failures.
  // CSD_RATIONALE_END
  generated := currentPrefix;
  helpers.cost := 0;
  cost := 0;
  var suffix: Prefix := [];
  var steps: nat := 0;
  var inDelim: bool := false;
  var contentInDelim: bool := false;

