  // delimiter tokens are encouraged, and the output remains parser-valid.
  // CSD_RATIONALE_END
  generated := currentPrefix;
  cost := 0;
  var steps: nat := 0;
  var favored: seq<Token> := ["<<", ">>"];

  while steps < maxSteps
    invariant generated == currentPrefix + generated[|currentPrefix|..]
    invariant parser.IsValidPrefix(generated)
    invariant |generated| <= |currentPrefix| + steps
    invariant cost == steps
    decreases maxSteps - steps
  {
    if parser.IsCompletePrefix(generated) {
      break;
    } else {
      var next := helpers.BoostedConstrainedStep(lm, parser, prompt, generated, favored, 1000.0, eosToken);
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        steps := steps + 1;
        cost := cost + 1;
      }
    }
  }
}

